def permutations(nums):
    out = []
    def go(cur, rest):
        if not rest:
            out.append(cur)
            return
        for i in range(len(rest)):
            go(cur + [rest[i]], rest[:i] + rest[i + 1:])
    go([], nums)
    return sorted(out)
